import{_ as d,C as s,o as n,c as e,j as i,E as l,a as r,a3 as o}from"./chunks/framework.C6R8kWFE.js";const T=JSON.parse('{"title":"3-hafta (Mentor)","description":"","frontmatter":{"title":"3-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"10-sinf (Cyber)","link":"/mentor/10-sinf-cyber/"},"n":3,"bob":"I-bob · Kiberxavfsizlikka kirish","lessons":[{"g":7,"title":"Xavfsizlikni anglash (2-qism): raqamli gigiyena, brauzer xavfsizligi va 2FA","lead":"Xavfsizlikni anglash tushunchasi (2-qism): raqamli gigiyena, brauzer xavfsizligi va ikki bosqichli autentifikatsiya (2FA)","link":"/mentor/10-sinf-cyber/hafta-03/dars-1","slide":"/slaydlar/10-sinf-cyber/hafta-03/dars-1.html","test":"/slaydlar/10-sinf-cyber/hafta-03/dars-1-test.html"},{"g":8,"title":"Xavfsizlikni anglash (3-qism): tahdidlarni modellashtirish, Red/Blue Team va CTF","lead":"Xavfsizlikni anglash tushunchasi (3-qism): tahdidlarni modellashtirish, Red Team vs Blue Team va CTF asoslari","link":"/mentor/10-sinf-cyber/hafta-03/dars-2","slide":"/slaydlar/10-sinf-cyber/hafta-03/dars-2.html","test":"/slaydlar/10-sinf-cyber/hafta-03/dars-2-test.html"},{"g":9,"title":"Tarmoq asoslari: mijoz-server arxitekturasi, topologiyalar, OSI va TCP/IP modellari","lead":"Tarmoq asoslari: mijoz-server arxitekturasi, topologiyalar, OSI va TCP/IP modellari","link":"/mentor/10-sinf-cyber/hafta-03/dars-3","slide":"/slaydlar/10-sinf-cyber/hafta-03/dars-3.html","test":"/slaydlar/10-sinf-cyber/hafta-03/dars-3-test.html"}],"test":"/slaydlar/10-sinf-cyber/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"mentor/10-sinf-cyber/hafta-03/index.md","filePath":"mentor/10-sinf-cyber/hafta-03/index.md"}'),h={name:"mentor/10-sinf-cyber/hafta-03/index.md"},m={class:"blk"},g={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},u={class:"blk"},y={id:"baholash-mezoni",tabindex:"-1"};function b(v,a,k,c,q,f){const t=s("Icon");return n(),e("div",null,[i("div",m,[i("h2",g,[l(t,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=o('<p>Ushbu haftada o&#39;tilgan darslar bo&#39;yicha mustaqil amaliy uyga vazifalar ro&#39;yxati:</p><hr><h2 id="_7-dars-raqamli-gigiyena-va-shaxsiy-kiberxavfsizlik" tabindex="-1">7-dars. Raqamli gigiyena va shaxsiy kiberxavfsizlik <a class="header-anchor" href="#_7-dars-raqamli-gigiyena-va-shaxsiy-kiberxavfsizlik" aria-label="Permalink to &quot;7-dars. Raqamli gigiyena va shaxsiy kiberxavfsizlik&quot;">​</a></h2><ol><li>O&#39;zingiz muntazam foydalanadigan brauzeringizga (Chrome, Firefox yoki Edge) <code>uBlock Origin</code> va <code>ClearURLs</code> kengaytmalarini o&#39;rnating. Har qanday 3 ta ommabop yangiliklar saytiga kirib, qancha kuzatuvchi (tracker) va reklama skriptlari bloklanganini qayd eting.</li><li>Shaxsiy kompyuteringiz yoki smartfoningizda shifrlangan xavfsiz DNS serverini (Cloudflare <code>1.1.1.1</code> yoki <code>1.1.1.2</code> zararli dasturlardan himoyalangan DNS) sozlang. Sozlash jarayonini skrinshotlar orqali hujjatlashtiring.</li><li>Telegram yoki Google hisobingizda 2-bosqichli tasdiqlash (2FA) yoqilganligini tekshiring, agar yoqilmagan bo&#39;lsa yoqing va maxfiy tiklash kodi/parolini ishonchli offline joyda saqlang.</li></ol><hr><h2 id="_8-dars-stride-tahdid-modeli-red-team-vs-blue-team-va-ctf-musobaqalari" tabindex="-1">8-dars. STRIDE tahdid modeli, Red Team vs Blue Team va CTF musobaqalari <a class="header-anchor" href="#_8-dars-stride-tahdid-modeli-red-team-vs-blue-team-va-ctf-musobaqalari" aria-label="Permalink to &quot;8-dars. STRIDE tahdid modeli, Red Team vs Blue Team va CTF musobaqalari&quot;">​</a></h2><ol><li>O&#39;zingiz bilgan bitta onlayn servis (masalan, maktab oshxonasi to&#39;lov ilovasi yoki onlayn kutubxona tizimi) uchun STRIDE modeli bo&#39;yicha tahdidlar tahlili jadvalini to&#39;ldiring: <ul><li><strong>S (Spoofing):</strong> Birov boshqa o&#39;quvchi nomidan tizimga kirish xavfi;</li><li><strong>T (Tampering):</strong> Hisobdagi balans yoki kitob ma&#39;lumotlarini o&#39;zgartirish xavfi;</li><li><strong>R (Repudiation):</strong> O&#39;tkazilgan to&#39;lov yoki olingan kitobni rad etish xavfi;</li><li><strong>I (Information Disclosure):</strong> O&#39;quvchilar telefon raqamlari yoki parollarining oqib ketishi;</li><li><strong>D (Denial of Service):</strong> Tizimni ko&#39;p so&#39;rovlar yuborib ishdan chiqarish;</li><li><strong>E (Elevation of Privilege):</strong> Oddiy o&#39;quvchining administrator huquqiga ega bo&#39;lib olishi.</li></ul></li><li>Red Team va Blue Team rollarini solishtiruvchi qisqa esse (1 sahifa) yozing: nega tashkilotlar uchun faqat himoyalanish (Blue Team) yetarli emas va doimiy mustaqil sinovlar (Red Team) talab etiladi?</li><li>CTF musobaqalarining asosiy yo&#39;nalishlari (Web, Forensics, Reverse, Pwn, Crypto) bo&#39;yicha konspekt tuzing.</li></ol><hr><h2 id="_9-dars-tarmoq-asoslari-topologiyalar-osi-modeli-va-tcp-ip-steki" tabindex="-1">9-dars. Tarmoq asoslari: topologiyalar, OSI modeli va TCP/IP steki <a class="header-anchor" href="#_9-dars-tarmoq-asoslari-topologiyalar-osi-modeli-va-tcp-ip-steki" aria-label="Permalink to &quot;9-dars. Tarmoq asoslari: topologiyalar, OSI modeli va TCP/IP steki&quot;">​</a></h2><ol><li>Yulduzsimon (Star) va To&#39;rsimon (Mesh) topologiyalarining kamida 3 tadan afzallik va kamchiliklarini taqqoslovchi jadval tuzing. Nima sababdan hozirgi zamonaviy lokal tarmoqlarda yulduzsimon topologiya keng qo&#39;llaniladi?</li><li>OSI modelining 7 ta qatlamini tartib bilan yozing va har bir qatlamda ishlaydigan kamida bittadan protokol yoki qurilmani ko&#39;rsating.</li><li>TCP va UDP protokollari o&#39;rtasidagi farqni tushuntiring: <ul><li>Nima sababdan veb-saytlarni yuklashda (HTTP/HTTPS) va fayl uzatishda TCP ishlatiladi?</li><li>Nima sababdan onlayn o&#39;yinlar, videoqo&#39;ng&#39;iroqlar va jonli efirlarda UDP afzal ko&#39;riladi?</li></ul></li><li>Kompyuteringiz terminalida <code>ping</code> va <code>traceroute</code> (yoki Windowsda <code>tracert</code>) buyruqlari orqali <code>google.com</code> yoki <code>edu.uz</code> manziliga tarmoq marshrutini tahlil qiling va natijalarni yozib oling.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-100-ballik-tizim" tabindex="-1">Baholash mezonlari (100 ballik tizim) <a class="header-anchor" href="#baholash-mezonlari-100-ballik-tizim" aria-label="Permalink to &quot;Baholash mezonlari (100 ballik tizim)&quot;">​</a></h3><ol><li><p><strong>Raqamli gigiyena va shaxsiy himoya ko&#39;nikmalari (30 ball):</strong></p><ul><li>Brauzer kengaytmalari va xavfsiz DNS sozlamalarini mustaqil amalga oshira olishi (15 ball);</li><li>2FA (ikki bosqichli autentifikatsiya) ahamiyatini tushunishi va amalda yoqa olishi (15 ball).</li></ul></li><li><p><strong>Tahdidlarni modellashtirish va jamoalar falsafasi (35 ball):</strong></p><ul><li>Tanlangan tizim uchun STRIDE ning barcha 6 ta toifasini to&#39;g&#39;ri va asosli tahlil qilgani (20 ball);</li><li>Red Team, Blue Team va Purple Team vazifalari o&#39;rtasidagi muvozanatni tushunishi (10 ball);</li><li>CTF yo&#39;nalishlarini to&#39;g&#39;ri ifodalashi (5 ball).</li></ul></li><li><p><strong>Tarmoq arxitekturasi va OSI modeli tahlili (35 ball):</strong></p><ul><li>Topologiyalar (Star, Mesh, Ring, Bus) xususiyatlarini to&#39;g&#39;ri ajratishi (10 ball);</li><li>OSI 7 qatlami va TCP/IP 4 qatlami o&#39;rtasidagi o&#39;zaro bog&#39;liqlikni to&#39;g&#39;ri tushuntirishi (15 ball);</li><li>TCP va UDP farqlarini ishonchli misollar bilan asoslay olishi, ping/traceroute natijalarini to&#39;g&#39;ri o&#39;qiy olishi (10 ball).</li></ul></li></ol><h3 id="kutiladigan-namunaviy-natijalar" tabindex="-1">Kutiladigan namunaviy natijalar <a class="header-anchor" href="#kutiladigan-namunaviy-natijalar" aria-label="Permalink to &quot;Kutiladigan namunaviy natijalar&quot;">​</a></h3><ul><li>STRIDE tahlilida o&#39;quvchi shunchaki umumiy gaplar yozmasdan, aniq tahdid ssenariysini (masalan: &quot;Tampering: foydalanuvchi HTTP so&#39;rovdagi narx parametrini o&#39;zgartirishi&quot;) keltirishi kerak;</li><li>Tarmoq vazifasida TCP ning 3 tomonlama bog&#39;lanishi (SYN, SYN-ACK, ACK) va UDP ning bog&#39;lanish o&#39;rnatmasligi (Connectionless) aniq tushuntirilishi shart.</li></ul>',16))]),i("div",u,[i("h2",y,[l(t,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=o('<p><strong>Mavzular:</strong></p><ol><li>Raqamli gigiyena va shaxsiy kiberxavfsizlik: parollar, 2FA, brauzer kengaytmalari, xavfsiz DNS</li><li>Tahdidlarni modellashtirish (STRIDE), xavfsizlik jamoalari (Red/Blue/Purple) va CTF musobaqalari</li><li>Tarmoq asoslari: topologiyalar, OSI 7 qatlam modeli, TCP/IP steki va TCP vs UDP</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Raqamli gigiyena</strong></td><td>Brauzer himoyasi (uBlock, ClearURLs), DoH/DNS sozlamalari, 2FA tamoyillari</td><td>30 ball</td></tr><tr><td><strong>STRIDE va Jamoalar</strong></td><td>STRIDE tahdid modeli tahlili, Red/Blue Team farqi, CTF formatlari</td><td>35 ball</td></tr><tr><td><strong>Tarmoq va OSI</strong></td><td>Topologiyalar, OSI 7 qatlami vazifalari, TCP handshake va UDP farqi</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Gigiyena (30)</th><th>STRIDE/Jamoa (35)</th><th>Tarmoq/OSI (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar OSI modelining yuqori qatlamlari (Application, Presentation, Session) o&#39;rtasidagi farqni hamda TCP 3-way handshake mexanizmini chalkashtirishi mumkin. Slaydlardagi vizual sxemalar va Wireshark yordamida bu jarayonni amalda ko&#39;rsatish tavsiya etiladi.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> O&#39;quvchilarga picoCTF yoki OverTheWire (Bandit) platformalarining boshlang&#39;ich laboratoriya topshiriqlarini bajarish tavsiya qilinishi mumkin.</li></ul>',11))])])}const p=d(h,[["render",b]]);export{T as __pageData,p as default};
